import{_ as o,o as t,c as r,ag as a}from"./chunks/framework.8tqBsFWt.js";const _=JSON.parse('{"title":"Proposal Tools","description":"","frontmatter":{},"headers":[],"relativePath":"reference/tools/proposals.md","filePath":"reference/tools/proposals.md"}'),d={name:"reference/tools/proposals.md"};function s(n,e,p,l,c,i){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="proposal-tools" tabindex="-1">Proposal Tools <a class="header-anchor" href="#proposal-tools" aria-label="Permalink to &quot;Proposal Tools&quot;">​</a></h1><p>Proposals model prospective work before it exists as a project — staffing lines, vendor commitments, live costing against a target efficiency ratio, and a capacity simulation for whether the team can actually take the work on. A proposal never touches operational reporting: it&#39;s excluded from every dashboard, forecast, and reminder VERA sends. It becomes real only when it&#39;s converted to a project, which is the first moment it appears anywhere else.</p><p>All proposal tools are <strong>Owner/Admin only</strong> and <strong>console-only</strong> — not reachable from Slack; use the web console.</p><hr><h2 id="create_proposal" tabindex="-1">create_proposal <a class="header-anchor" href="#create_proposal" aria-label="Permalink to &quot;create_proposal {#create_proposal}&quot;">​</a></h2><p>Start a new proposal.</p><p><strong>Console-only</strong> — not reachable from Slack; use the web console.</p><p><strong>Writes to</strong>: proposals</p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td>✅</td><td></td></tr><tr><td><code>name</code></td><td>✅</td><td></td></tr><tr><td><code>prospect_name</code></td><td></td><td>The prospective client&#39;s name</td></tr><tr><td><code>project_type</code></td><td></td><td><code>&quot;T&amp;M&quot;</code> | <code>&quot;Fixed Price&quot;</code> | <code>&quot;Pro Bono&quot;</code> | <code>&quot;Internal&quot;</code> — defaults to <code>&quot;Fixed Price&quot;</code></td></tr><tr><td><code>contract_value</code></td><td></td><td></td></tr><tr><td><code>target_ler</code></td><td></td><td>Target labor efficiency ratio for this proposal; falls back to the tenant&#39;s standard target when omitted</td></tr><tr><td><code>hours_budget</code></td><td></td><td></td></tr><tr><td><code>deadline</code></td><td></td><td><code>YYYY-MM-DD</code></td></tr><tr><td><code>notes</code></td><td></td><td></td></tr></tbody></table><p>New proposals start as <code>draft</code>. A proposal is created and edited entirely apart from VERA&#39;s operational data — nothing here is joined into any project, financial, or capacity report until it&#39;s converted.</p><hr><h2 id="list_proposals" tabindex="-1">list_proposals <a class="header-anchor" href="#list_proposals" aria-label="Permalink to &quot;list_proposals {#list_proposals}&quot;">​</a></h2><p>List proposals.</p><p><strong>Reads from</strong>: proposals</p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td></td></tr><tr><td><code>status</code></td><td>Optional filter: <code>&quot;draft&quot;</code> | <code>&quot;won&quot;</code> | <code>&quot;lost&quot;</code> | <code>&quot;converted&quot;</code></td></tr></tbody></table><hr><h2 id="update_proposal" tabindex="-1">update_proposal <a class="header-anchor" href="#update_proposal" aria-label="Permalink to &quot;update_proposal {#update_proposal}&quot;">​</a></h2><p>Update one or more fields on a proposal.</p><p><strong>Console-only</strong> — not reachable from Slack; use the web console.</p><p><strong>Updates</strong>: proposals</p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code>, <code>id</code>, and any of <code>name</code>, <code>prospect_name</code>, <code>project_type</code>, <code>contract_value</code>, <code>target_ler</code>, <code>hours_budget</code>, <code>status</code>, <code>notes</code>, <code>deadline</code></p><p>A proposal that is <strong>closed</strong> — <code>status</code> is <code>&quot;won&quot;</code> or <code>&quot;lost&quot;</code>, or it has already been converted to a project — can no longer be edited.</p><hr><h2 id="delete_proposal" tabindex="-1">delete_proposal <a class="header-anchor" href="#delete_proposal" aria-label="Permalink to &quot;delete_proposal {#delete_proposal}&quot;">​</a></h2><p>Permanently delete a proposal. Proposals are speculative, so this is a hard delete, not an archive.</p><p><strong>Console-only</strong> — not reachable from Slack; use the web console.</p><p><strong>Deletes from</strong>: proposals</p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code>, <code>id</code></p><p>A proposal that has already been converted to a project cannot be deleted — once real work exists downstream of it, the proposal record stays as the paper trail.</p><hr><h2 id="create_proposal_role" tabindex="-1">create_proposal_role <a class="header-anchor" href="#create_proposal_role" aria-label="Permalink to &quot;create_proposal_role {#create_proposal_role}&quot;">​</a></h2><p>Add a staffing line to a proposal — a discipline and/or a specific person, with planned hours and (for T&amp;M) a proposed billing rate.</p><p><strong>Console-only</strong> — not reachable from Slack; use the web console.</p><p><strong>Writes to</strong>: proposal staffing lines</p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td>✅</td><td></td></tr><tr><td><code>proposal_id</code></td><td>✅</td><td></td></tr><tr><td><code>discipline_id</code></td><td></td><td></td></tr><tr><td><code>user_id</code></td><td></td><td>A specific person, if the line is pinned to one</td></tr><tr><td><code>planned_hours</code></td><td></td><td></td></tr><tr><td><code>billing_rate</code></td><td></td><td>For T&amp;M proposals</td></tr><tr><td><code>task</code></td><td></td><td></td></tr><tr><td><code>start_date</code></td><td></td><td>Staffing-line window start, <code>YYYY-MM-DD</code>. Both-or-neither with <code>end_date</code>.</td></tr><tr><td><code>end_date</code></td><td></td><td>Staffing-line window end, <code>YYYY-MM-DD</code>.</td></tr><tr><td><code>week_hours</code></td><td></td><td>How the line&#39;s planned hours land across the weeks of its window — array of <code>{ week, hours }</code>. Requires a window; the sum can&#39;t exceed <code>planned_hours</code>.</td></tr></tbody></table><p>Costing precedence for an unrated line follows the same order <code>get_proposal_costing</code> uses: the pinned person&#39;s own rate, then the discipline&#39;s blended rate, then the agency&#39;s blended rate.</p><hr><h2 id="update_proposal_role" tabindex="-1">update_proposal_role <a class="header-anchor" href="#update_proposal_role" aria-label="Permalink to &quot;update_proposal_role {#update_proposal_role}&quot;">​</a></h2><p>Update a staffing line.</p><p><strong>Console-only</strong> — not reachable from Slack; use the web console.</p><p><strong>Updates</strong>: proposal staffing lines</p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code>, <code>id</code>, and any of <code>discipline_id</code>, <code>user_id</code>, <code>planned_hours</code>, <code>billing_rate</code>, <code>task</code></p><p><strong>Window and shape (presence-based, same rules as an allocation envelope):</strong> <code>start_date</code>/<code>end_date</code> are both-or-neither — omit both to leave the window untouched, send both to set or replace it, send both empty to clear it. <code>week_hours</code> is presence-based too — omitted leaves the shape untouched, an empty array clears it, a non-empty array is validated (every week a Monday inside the window, sum capped at <code>planned_hours</code>) and written. <code>week_hours</code> requires the line to already have a window.</p><p>Refused on a closed proposal (status <code>won</code>, <code>lost</code>, or already converted).</p><hr><h2 id="delete_proposal_role" tabindex="-1">delete_proposal_role <a class="header-anchor" href="#delete_proposal_role" aria-label="Permalink to &quot;delete_proposal_role {#delete_proposal_role}&quot;">​</a></h2><p>Remove a staffing line from a proposal.</p><p><strong>Console-only</strong> — not reachable from Slack; use the web console.</p><p><strong>Deletes from</strong>: proposal staffing lines</p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code>, <code>id</code></p><p>Refused on a closed proposal.</p><hr><h2 id="create_proposal_liability" tabindex="-1">create_proposal_liability <a class="header-anchor" href="#create_proposal_liability" aria-label="Permalink to &quot;create_proposal_liability {#create_proposal_liability}&quot;">​</a></h2><p>Add a vendor commitment to a proposal — a fixed-fee line for work the agency plans to outsource rather than staff internally.</p><p><strong>Console-only</strong> — not reachable from Slack; use the web console.</p><p><strong>Writes to</strong>: proposal vendor commitments</p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td>✅</td><td></td></tr><tr><td><code>proposal_id</code></td><td>✅</td><td></td></tr><tr><td><code>vendor_user_id</code></td><td>✅</td><td>Must be an existing user with the vendor employment type</td></tr><tr><td><code>description</code></td><td>✅</td><td></td></tr><tr><td><code>agreed_amount</code></td><td>✅</td><td>Positive number</td></tr><tr><td><code>agreed_hours</code></td><td></td><td></td></tr></tbody></table><p>The vendor must already exist as a user before it can be committed on a proposal — a new vendor is onboarded on the Users page first.</p><p>Refused on a closed proposal.</p><hr><h2 id="update_proposal_liability" tabindex="-1">update_proposal_liability <a class="header-anchor" href="#update_proposal_liability" aria-label="Permalink to &quot;update_proposal_liability {#update_proposal_liability}&quot;">​</a></h2><p>Update a vendor commitment on a proposal.</p><p><strong>Console-only</strong> — not reachable from Slack; use the web console.</p><p><strong>Updates</strong>: proposal vendor commitments</p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code>, <code>id</code>, and any of <code>vendor_user_id</code>, <code>description</code>, <code>agreed_amount</code>, <code>agreed_hours</code></p><p>Refused on a closed proposal.</p><hr><h2 id="delete_proposal_liability" tabindex="-1">delete_proposal_liability <a class="header-anchor" href="#delete_proposal_liability" aria-label="Permalink to &quot;delete_proposal_liability {#delete_proposal_liability}&quot;">​</a></h2><p>Remove a vendor commitment from a proposal.</p><p><strong>Console-only</strong> — not reachable from Slack; use the web console.</p><p><strong>Deletes from</strong>: proposal vendor commitments</p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code>, <code>id</code></p><p>Refused on a closed proposal.</p><hr><h2 id="get_proposal_costing" tabindex="-1">get_proposal_costing <a class="header-anchor" href="#get_proposal_costing" aria-label="Permalink to &quot;get_proposal_costing {#get_proposal_costing}&quot;">​</a></h2><p>Live costing snapshot for a proposal — every staffing line and vendor commitment, each cost-rated, plus the resulting P&amp;L.</p><p><strong>Reads from</strong>: proposals, proposal staffing lines, proposal vendor commitments</p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code>, <code>proposal_id</code></p><p><strong>Returns</strong>: the proposal; each staffing line annotated with its resolved <code>cost_rate</code> and <code>rate_source</code> (<code>&quot;person&quot;</code> | <code>&quot;discipline&quot;</code> | <code>&quot;agency&quot;</code>); the vendor commitments; and a <code>pnl</code> object with <code>revenue</code>, <code>cost</code>, <code>profit</code>, <code>ler</code>, <code>margin_pct</code>, <code>target_ler</code>, <code>people_budget</code> (revenue ÷ target LER), <code>over_budget</code>, <code>total_hours</code>, <code>committed_envelope</code>, <code>committed_liability</code>, and <code>vendor_hours</code>.</p><p>Revenue is the sum of each staffing line&#39;s hours × its proposed billing rate for a T&amp;M proposal, or the proposal&#39;s contract value otherwise (Pro Bono and Internal naturally price at $0). This is a read-only computation — nothing here writes anything.</p>',84)])])}const u=o(d,[["render",s]]);export{_ as __pageData,u as default};
